-- 0030: аналитика вопросов (сохранённый результат пересчёта) и мини-проверка после лекции.
-- analytics: k = 'qstats' — JSON сводки по вопросам; страница читает его (плюс кэш worker), тяжёлая агрегация — только по кнопке «Пересчитать».
CREATE TABLE IF NOT EXISTS analytics (
  k TEXT PRIMARY KEY,
  v TEXT NOT NULL,
  updated_by TEXT,
  updated_at INTEGER NOT NULL
);
-- lecture_quiz: 1–3 вопроса к лекции (tools/content/lecture-quiz.js); quote — абзац лекции, если у вопроса нет своей цитаты.
CREATE TABLE IF NOT EXISTS lecture_quiz (
  lecture_id INTEGER NOT NULL,
  question_id INTEGER NOT NULL,
  position INTEGER NOT NULL DEFAULT 0,
  quote TEXT NOT NULL DEFAULT '',
  PRIMARY KEY (lecture_id, question_id)
);
