INSERT OR IGNORE INTO lecture_quiz (lecture_id, question_id, position, quote) SELECT l.id, q.id, 1, '**1.1.** Нападать на Федеральную тюрьму могут только участники криминальных фракций / зарегистрированные семьи. [Demorgan 120 минут]' FROM lectures l, questions q WHERE l.id = 12 AND l.title = 'Лекция 1. Кто, когда и в каком составе нападает' AND q.id = 1022 AND q.ext_id = 'ooc-ft-q04';
INSERT OR IGNORE INTO lecture_quiz (lecture_id, question_id, position, quote) SELECT l.id, q.id, 2, '**1.4.** Нападение на федеральную тюрьму происходит 1 раз в сутки с 18:00 до 22:00 с помощью внутриигрового функционала. [Demorgan 360 минут]' FROM lectures l, questions q WHERE l.id = 12 AND l.title = 'Лекция 1. Кто, когда и в каком составе нападает' AND q.id = 1020 AND q.ext_id = 'ooc-ft-q02';
INSERT OR IGNORE INTO lecture_quiz (lecture_id, question_id, position, quote) SELECT l.id, q.id, 3, '> Примечание: Действия провокационного характера, а именно проникновение, байт на стрельбу внутри или на вокруг ФСИН, будет расцениваться как нарушение данного свода правил. (На заключенных не распространяется)' FROM lectures l, questions q WHERE l.id = 12 AND l.title = 'Лекция 1. Кто, когда и в каком составе нападает' AND q.id = 1034 AND q.ext_id = 'ooc-ft-q16';
INSERT OR IGNORE INTO lecture_quiz (lecture_id, question_id, position, quote) SELECT l.id, q.id, 1, '- Похищать и грабить сотрудников государственных фракций при нападении запрещено. - Транспорт на территории ФСИН и высадка с вертолётов запрещены; покинуть территорию после начала и вернуться на неё нельзя.' FROM lectures l, questions q WHERE l.id = 13 AND l.title = 'Лекция 2. Ограничения во время нападения' AND q.id = 1033 AND q.ext_id = 'ooc-ft-q15';
