INSERT OR IGNORE INTO lecture_quiz (lecture_id, question_id, position, quote) SELECT l.id, q.id, 1, '**2.2.** Запрещено блокировать дороги и входы транспортом на территории федеральной тюрьмы. [Demorgan 120 минут]' FROM lectures l, questions q WHERE l.id = 14 AND l.title = 'Лекция 3. Правила для государственных организаций' AND q.id = 1026 AND q.ext_id = 'ooc-ft-q08';
INSERT OR IGNORE INTO lecture_quiz (lecture_id, question_id, position, quote) SELECT l.id, q.id, 2, '**2.5.** Запрещено отбивать нападение без оружия. [Demorgan 120 минут]' FROM lectures l, questions q WHERE l.id = 14 AND l.title = 'Лекция 3. Правила для государственных организаций' AND q.id = 1029 AND q.ext_id = 'ooc-ft-q11';
INSERT OR IGNORE INTO lecture_quiz (lecture_id, question_id, position, quote) SELECT l.id, q.id, 3, '- Отбивать нападение — только с оружием и только на фракционном транспорте. - После смерти — не возвращаться на территорию до конца нападения (самое строгое наказание главы — Demorgan 420 минут). - Не блокировать дороги и входы транспортом; не поднимать сотрудников до окончания нападения.' FROM lectures l, questions q WHERE l.id = 14 AND l.title = 'Лекция 3. Правила для государственных организаций' AND q.id = 1028 AND q.ext_id = 'ooc-ft-q10';
INSERT OR IGNORE INTO lecture_quiz (lecture_id, question_id, position, quote) SELECT l.id, q.id, 1, '**3.2.** Требуется вести минимум 2 видеозаписи от игроков фракции / семьи напавшей на тюрьму. [Предупреждение лидеру]' FROM lectures l, questions q WHERE l.id = 15 AND l.title = 'Лекция 4. Правила для криминальных организаций' AND q.id = 1035 AND q.ext_id = 'ooc-ft-q17';
INSERT OR IGNORE INTO lecture_quiz (lecture_id, question_id, position, quote) SELECT l.id, q.id, 2, '**3.3.** Совершать нападение на Федеральную тюрьму разрешено не более двум криминальным фракциям/семьям (нападающая сторона + 1 криминальная фракция/семья в IC-союзе). Иным криминальным фракциям/семьям запрещено принимать участие в событии или оказывать помощь любой из сторон. [Demorgan 60 минут / Предупреждение лидеру]' FROM lectures l, questions q WHERE l.id = 15 AND l.title = 'Лекция 4. Правила для криминальных организаций' AND q.id = 1022 AND q.ext_id = 'ooc-ft-q04';
INSERT OR IGNORE INTO lecture_quiz (lecture_id, question_id, position, quote) SELECT l.id, q.id, 3, '> Исключение: Заключенные вправе примкнуть к нападающей стороне с целью побега и (или) содействия захвату Федеральной тюрьмы.' FROM lectures l, questions q WHERE l.id = 15 AND l.title = 'Лекция 4. Правила для криминальных организаций' AND q.id = 1025 AND q.ext_id = 'ooc-ft-q07';
INSERT OR IGNORE INTO lecture_quiz (lecture_id, question_id, position, quote) SELECT l.id, q.id, 1, '> Исключение: на сотрудников ''ЦГБ'' правила PG -действует' FROM lectures l, questions q WHERE l.id = 16 AND l.title = 'Лекция 1. Общие положения войны за КрАЗ' AND q.id = 1038 AND q.ext_id = 'ooc-kraz-q02';
INSERT OR IGNORE INTO lecture_quiz (lecture_id, question_id, position, quote) SELECT l.id, q.id, 2, '**1.5.** Запрещается стрелять в безоружных гражданских людей или по проезжающим машинам гражданских без предупреждения и требования удалиться. [Pacifist DM]' FROM lectures l, questions q WHERE l.id = 16 AND l.title = 'Лекция 1. Общие положения войны за КрАЗ' AND q.id = 1040 AND q.ext_id = 'ooc-kraz-q04';
INSERT OR IGNORE INTO lecture_quiz (lecture_id, question_id, position, quote) SELECT l.id, q.id, 3, '**1.8.** На событии ВЗК ( Война за КрАЗ ) - запрещено нарушение правила DB, даже при наличии IC причины. [Demorgan DB]' FROM lectures l, questions q WHERE l.id = 16 AND l.title = 'Лекция 1. Общие положения войны за КрАЗ' AND q.id = 1045 AND q.ext_id = 'ooc-kraz-q09';
