INSERT OR IGNORE INTO lecture_quiz (lecture_id, question_id, position, quote) SELECT l.id, q.id, 2, '> Пояснение: Во время действия таймера, запрещается открывать огонь из транспортных средств. При движении грузовика, стрельба из транспортных средств разрешается.' FROM lectures l, questions q WHERE l.id = 17 AND l.title = 'Лекция 2. Территория и транспорт' AND q.id = 1042 AND q.ext_id = 'ooc-kraz-q06';
INSERT OR IGNORE INTO lecture_quiz (lecture_id, question_id, position, quote) SELECT l.id, q.id, 3, '**1.18.** При перевозке грузовика ( КрАз ) стороны обязуются передвигаться исключительно по асфальтированной / грунтовой дороге. [Demorgan NRD]' FROM lectures l, questions q WHERE l.id = 17 AND l.title = 'Лекция 2. Территория и транспорт' AND q.id = 1043 AND q.ext_id = 'ooc-kraz-q07';
