INSERT OR IGNORE INTO lecture_quiz (lecture_id, question_id, position, quote) SELECT l.id, q.id, 3, '**1.9.** Разрешено продолжать стрельбу после окончания налета в течении 3 минут.' FROM lectures l, questions q WHERE l.id = 20 AND l.title = 'Лекция 1. Стороны налёта и общие положения' AND q.id = 1055 AND q.ext_id = 'ooc-nalety-q03';
INSERT OR IGNORE INTO lecture_quiz (lecture_id, question_id, position, quote) SELECT l.id, q.id, 1, '> Примечание: машины нужно оставлять за зоной, если ваш автомобиль уже в зоне налета нельзя ездить на нем во время перестрелки, пока не закончится налёт.' FROM lectures l, questions q WHERE l.id = 21 AND l.title = 'Лекция 2. Гражданские, транспорт и территория' AND q.id = 1058 AND q.ext_id = 'ooc-nalety-q06';
INSERT OR IGNORE INTO lecture_quiz (lecture_id, question_id, position, quote) SELECT l.id, q.id, 2, '> Примечание: Нужно собираться на территории налета до его начала, нельзя приезжать на территорию налета после начала.' FROM lectures l, questions q WHERE l.id = 21 AND l.title = 'Лекция 2. Гражданские, транспорт и территория' AND q.id = 1059 AND q.ext_id = 'ooc-nalety-q07';
INSERT OR IGNORE INTO lecture_quiz (lecture_id, question_id, position, quote) SELECT l.id, q.id, 3, '- Стрелять в безоружных гражданских и по машинам без предупреждения и требования удалиться запрещено. - Транспорт в зоне налёта не используется; покидать территорию налёта нельзя (с исключениями).' FROM lectures l, questions q WHERE l.id = 21 AND l.title = 'Лекция 2. Гражданские, транспорт и территория' AND q.id = 1057 AND q.ext_id = 'ooc-nalety-q05';
INSERT OR IGNORE INTO lecture_quiz (lecture_id, question_id, position, quote) SELECT l.id, q.id, 1, '**1.12.** Участие в налетах от криминальных организаций / семей разрешено только на фракционном / личном транспорте окрашенном в цвет фракции / семьи. [Demorgan 120 минут]' FROM lectures l, questions q WHERE l.id = 22 AND l.title = 'Лекция 3. Кто может участвовать' AND q.id = 1068 AND q.ext_id = 'ooc-nalety-q16';
INSERT OR IGNORE INTO lecture_quiz (lecture_id, question_id, position, quote) SELECT l.id, q.id, 2, '- Сотрудникам ЦГБ участвовать в налёте запрещено; поднимать людей можно вне зоны. - Криминальная организация не участвует в семейном налёте, и наоборот.' FROM lectures l, questions q WHERE l.id = 22 AND l.title = 'Лекция 3. Кто может участвовать' AND q.id = 1061 AND q.ext_id = 'ooc-nalety-q09';
INSERT OR IGNORE INTO lecture_quiz (lecture_id, question_id, position, quote) SELECT l.id, q.id, 3, '- Сотрудникам ЦГБ участвовать в налёте запрещено; поднимать людей можно вне зоны. - Криминальная организация не участвует в семейном налёте, и наоборот.' FROM lectures l, questions q WHERE l.id = 22 AND l.title = 'Лекция 3. Кто может участвовать' AND q.id = 1060 AND q.ext_id = 'ooc-nalety-q08';
INSERT OR IGNORE INTO lecture_quiz (lecture_id, question_id, position, quote) SELECT l.id, q.id, 1, '**1.3.** Сотрудникам государственных организаций запрещено превышение своих должностных полномочий (применение грубой физической силы, угрозы, злоупотребление наручниками и электрошокером) [Warn]' FROM lectures l, questions q WHERE l.id = 24 AND l.title = 'Лекция 1. Кто такие госслужащие и главные запреты' AND q.id = 1069 AND q.ext_id = 'ooc-opgo-q01';
INSERT OR IGNORE INTO lecture_quiz (lecture_id, question_id, position, quote) SELECT l.id, q.id, 2, '**1.6** Запрещено первым оскорблять, провоцировать, использовать унизительные анимации, а также грубо выражаться в присутствии / на задержанного или посторонних граждан. [Demorgan 120 минут / warn]' FROM lectures l, questions q WHERE l.id = 24 AND l.title = 'Лекция 1. Кто такие госслужащие и главные запреты' AND q.id = 1072 AND q.ext_id = 'ooc-opgo-q04';
INSERT OR IGNORE INTO lecture_quiz (lecture_id, question_id, position, quote) SELECT l.id, q.id, 3, '**1.31.** Сотрудникам государственных организаций категорически запрещается добивать игроков при любых обстоятельствах. [Demorgan 60-120 минут]' FROM lectures l, questions q WHERE l.id = 24 AND l.title = 'Лекция 1. Кто такие госслужащие и главные запреты' AND q.id = 1073 AND q.ext_id = 'ooc-opgo-q05';
INSERT OR IGNORE INTO lecture_quiz (lecture_id, question_id, position, quote) SELECT l.id, q.id, 1, '> Примечание: В случае если сотрудник государственных организаций отказывается называть права гражданина - он несет ответственность за нарушение правил государственных организаций, если же сотрудник назвал хотя бы 1 и более статей - это решается через IC. Гражданин, запрашивающий свои права должен чётко запросить разъяснение, чтобы сотрудник это услышал.' FROM lectures l, questions q WHERE l.id = 25 AND l.title = 'Лекция 2. Задержание и процессуальные действия' AND q.id = 1075 AND q.ext_id = 'ooc-opgo-q07';
INSERT OR IGNORE INTO lecture_quiz (lecture_id, question_id, position, quote) SELECT l.id, q.id, 2, '**1.24.** Оформить розыск можно исключительно при наличии IC причины. Розыск, который выдается системно является IC. [Warn]' FROM lectures l, questions q WHERE l.id = 25 AND l.title = 'Лекция 2. Задержание и процессуальные действия' AND q.id = 1078 AND q.ext_id = 'ooc-opgo-q10';
INSERT OR IGNORE INTO lecture_quiz (lecture_id, question_id, position, quote) SELECT l.id, q.id, 3, '- При задержании назвать причину и разъяснить права; предложить и запросить адвоката через «Гос.Структуры». - Доказательства применённого наказания и IC-причины розыска хранить 72 часа. - Штраф, обыск, конфискация — только через функционал и с причиной.' FROM lectures l, questions q WHERE l.id = 25 AND l.title = 'Лекция 2. Задержание и процессуальные действия' AND q.id = 1077 AND q.ext_id = 'ooc-opgo-q09';
INSERT OR IGNORE INTO lecture_quiz (lecture_id, question_id, position, quote) SELECT l.id, q.id, 1, '**1.14.** Сотрудникам государственных организаций запрещено проводить обыск и конфискацию каких либо предметов без веской IC причины, или в момент когда преступник у которого проводится конфискация находится без сознания (в ноке). [Warn]' FROM lectures l, questions q WHERE l.id = 26 AND l.title = 'Лекция 3. Служебная дисциплина' AND q.id = 1079 AND q.ext_id = 'ooc-opgo-q11';
INSERT OR IGNORE INTO lecture_quiz (lecture_id, question_id, position, quote) SELECT l.id, q.id, 2, '**1.17.** Сотрудникам государственных организаций запрещается применение огнестрельного оружия против невооруженного преступника. Если преступник не имеет оружия и пытается скрыться, открывать огонь на поражение разрешается только после исчерпания всех возможных средств остановки и задержания преступника (приказ, шокер, погоня и т.д.). [Demorgan 240 минут]' FROM lectures l, questions q WHERE l.id = 26 AND l.title = 'Лекция 3. Служебная дисциплина' AND q.id = 1083 AND q.ext_id = 'ooc-opgo-q15';
INSERT OR IGNORE INTO lecture_quiz (lecture_id, question_id, position, quote) SELECT l.id, q.id, 3, '**1.21.** Запрещено брать обмундирование (как предмет) со склада. [Слив склада]' FROM lectures l, questions q WHERE l.id = 26 AND l.title = 'Лекция 3. Служебная дисциплина' AND q.id = 1086 AND q.ext_id = 'ooc-opgo-q18';
INSERT OR IGNORE INTO lecture_quiz (lecture_id, question_id, position, quote) SELECT l.id, q.id, 1, '8.2.1. Вооруженные Силы имеют право на применение тяжелой бронетехники (танки, бронетранспортеры) только в случае объявления «Военного положения» или в рамках тренировок, учений на территории военной части и полигона.' FROM lectures l, questions q WHERE l.id = 27 AND l.title = 'Лекция 4. Взаимоотношения фракций и Вооружённые Силы' AND q.id = 1088 AND q.ext_id = 'ooc-opgo-q20';
INSERT OR IGNORE INTO lecture_quiz (lecture_id, question_id, position, quote) SELECT l.id, q.id, 2, '- Задерживать сотрудников других госорганизаций при исполнении нельзя — кроме случаев из исключения к п. 2.1. - Вооружённые Силы — основная силовая организация: поставки, КМБ, охрана; тяжёлая бронетехника — только при «Военном положении» или на тренировках / учениях на территории в/ч и полигона (п. 8.2.1, по согласованию с Главным куратором).' FROM lectures l, questions q WHERE l.id = 27 AND l.title = 'Лекция 4. Взаимоотношения фракций и Вооружённые Силы' AND q.id = 1087 AND q.ext_id = 'ooc-opgo-q19';
INSERT OR IGNORE INTO lecture_quiz (lecture_id, question_id, position, quote) SELECT l.id, q.id, 1, '**10.4.** Во время «дня блата» и в течении 7 дней после него запрещены любые переводы из фракции. [Warn]' FROM lectures l, questions q WHERE l.id = 28 AND l.title = 'Лекция 5. Переводы, увольнения и отстранения' AND q.id = 1090 AND q.ext_id = 'ooc-opgo-q22';
INSERT OR IGNORE INTO lecture_quiz (lecture_id, question_id, position, quote) SELECT l.id, q.id, 2, '**10.5.** Перевод из фракции во фракцию возможен только при условии нахождения во фракции на одном звании не менее 3 дней. [Warn]' FROM lectures l, questions q WHERE l.id = 28 AND l.title = 'Лекция 5. Переводы, увольнения и отстранения' AND q.id = 1089 AND q.ext_id = 'ooc-opgo-q21';
INSERT OR IGNORE INTO lecture_quiz (lecture_id, question_id, position, quote) SELECT l.id, q.id, 3, '**12.2.** Запрещено отстраннение государственных служащих на выборных должностях (лидер Правительства, депутаты Госдумы), кроме решения суда. [Предупреждение лидеру фракции, Warn сотруднику]' FROM lectures l, questions q WHERE l.id = 28 AND l.title = 'Лекция 5. Переводы, увольнения и отстранения' AND q.id = 1091 AND q.ext_id = 'ooc-opgo-q23';
INSERT OR IGNORE INTO lecture_quiz (lecture_id, question_id, position, quote) SELECT l.id, q.id, 1, 'ПКС регулируют захваты государственных зданий (теракты). Военнослужащий ВП может оказаться и заложником, и участником ответных действий силовых структур.' FROM lectures l, questions q WHERE l.id = 29 AND l.title = 'Лекция 1. Захват государственного здания: цели и условия' AND q.id = 1108 AND q.ext_id = 'ooc-pks-q17';
