INSERT OR IGNORE INTO lecture_quiz (lecture_id, question_id, position, quote) SELECT l.id, q.id, 1, '**1.10.** Во время захвата государственного здания группировка может взять 5 человек в заложники, которые находились в здании, после чего выкупить их согласно цене по правилам похищений.' FROM lectures l, questions q WHERE l.id = 30 AND l.title = 'Лекция 2. Ход захвата: заложники, переговоры, время' AND q.id = 1099 AND q.ext_id = 'ooc-pks-q08';
