INSERT OR IGNORE INTO lecture_quiz (lecture_id, question_id, position, quote) SELECT l.id, q.id, 1, '**2.3.** Запрещено покидать зону захвата вместе с заложником.' FROM lectures l, questions q WHERE l.id = 31 AND l.title = 'Лекция 3. Что запрещено захватчикам' AND q.id = 1100 AND q.ext_id = 'ooc-pks-q09';
INSERT OR IGNORE INTO lecture_quiz (lecture_id, question_id, position, quote) SELECT l.id, q.id, 2, '**2.7.** Запрещено выдавать за заложников участников захвата. [Предупреждение лидеру]' FROM lectures l, questions q WHERE l.id = 31 AND l.title = 'Лекция 3. Что запрещено захватчикам' AND q.id = 1108 AND q.ext_id = 'ooc-pks-q17';
INSERT OR IGNORE INTO lecture_quiz (lecture_id, question_id, position, quote) SELECT l.id, q.id, 3, '**2.11.** Захватчикам запрещено провоцировать государственных служащих. [Demorgan 240 минут]' FROM lectures l, questions q WHERE l.id = 31 AND l.title = 'Лекция 3. Что запрещено захватчикам' AND q.id = 1109 AND q.ext_id = 'ooc-pks-q18';
