INSERT OR IGNORE INTO lecture_quiz (lecture_id, question_id, position, quote) SELECT l.id, q.id, 2, '**3.5.** Разрешено начинать штурм, если переговорщика взяли в заложники или убили.' FROM lectures l, questions q WHERE l.id = 32 AND l.title = 'Лекция 4. Действия государственных организаций' AND q.id = 1103 AND q.ext_id = 'ooc-pks-q12';
INSERT OR IGNORE INTO lecture_quiz (lecture_id, question_id, position, quote) SELECT l.id, q.id, 3, '- Выезжать на захваты могут все сотрудники силовых структур; приоритет — у ФСБ, все госфракции на событии подчиняются лидеру ФСБ (кроме правительства). - Штурм разрешён, если переговорщика взяли в заложники или убили, а также при неадекватных требованиях. - Преследовать, перекрывать дороги и патрулировать можно вне радиуса требований; в зелёном коридоре — нельзя.' FROM lectures l, questions q WHERE l.id = 32 AND l.title = 'Лекция 4. Действия государственных организаций' AND q.id = 1102 AND q.ext_id = 'ooc-pks-q11';
INSERT OR IGNORE INTO lecture_quiz (lecture_id, question_id, position, quote) SELECT l.id, q.id, 1, '**1.1** Для государственных поставок (далее - поставок) / ограбления поставок (далее - ограбления) PG не действует на участвующие стороны ("Атакующая" и "Обороняющаяся").' FROM lectures l, questions q WHERE l.id = 33 AND l.title = 'Лекция 1. Поставки и ограбления: общие положения' AND q.id = 1110 AND q.ext_id = 'ooc-poip-q01';
INSERT OR IGNORE INTO lecture_quiz (lecture_id, question_id, position, quote) SELECT l.id, q.id, 2, '**1.6.** Запрещается покидать территорию ограбления / поставки. [Demorgan 120 минут]' FROM lectures l, questions q WHERE l.id = 33 AND l.title = 'Лекция 1. Поставки и ограбления: общие положения' AND q.id = 1112 AND q.ext_id = 'ooc-poip-q03';
INSERT OR IGNORE INTO lecture_quiz (lecture_id, question_id, position, quote) SELECT l.id, q.id, 3, '> Исключение: игроку можно покинуть территорию с целью выгрузки поставочных ресурсов (далее - ресурсов) и вернуться обратно на этом же поставочном транспорте если поставочный транспорт всего один, за исключением государственных организаций; Можно покинуть расстояние указанной территории с целью предупредить стоящего гражданина о происходящем (расценивается как предупреждение); Атакующей стороне разрешается покинуть территорию без использования Т/С вне завимости от ситуации. [Предупреждение / Demorgan 120 минут]' FROM lectures l, questions q WHERE l.id = 33 AND l.title = 'Лекция 1. Поставки и ограбления: общие положения' AND q.id = 1114 AND q.ext_id = 'ooc-poip-q05';
