INSERT OR IGNORE INTO lecture_quiz (lecture_id, question_id, position, quote) SELECT l.id, q.id, 3, '**1.8.** Запрещено использование вертолётов на ограблении/поставке. Разрешено летать на вертолете рядом с ограблением/поставкой с целю сбора/передачи информации, не залетая в зону события. [Demorgan 90 минут]' FROM lectures l, questions q WHERE l.id = 34 AND l.title = 'Лекция 2. Огонь, транспорт и снаряжение' AND q.id = 1113 AND q.ext_id = 'ooc-poip-q04';
INSERT OR IGNORE INTO lecture_quiz (lecture_id, question_id, position, quote) SELECT l.id, q.id, 1, '**1.19.** Сотрудникам ФСИН запрещается участвовать на любых поставках / ограблениях [Demorgan 120 минут]' FROM lectures l, questions q WHERE l.id = 35 AND l.title = 'Лекция 3. Кто участвует и на чём' AND q.id = 1116 AND q.ext_id = 'ooc-poip-q07';
INSERT OR IGNORE INTO lecture_quiz (lecture_id, question_id, position, quote) SELECT l.id, q.id, 2, '**2.2.** Участие в ограблениях / поставках разрешено только на фракционном / личном транспорте окрашенном в цвет фракции / семьи. [Demorgan 240 минут]' FROM lectures l, questions q WHERE l.id = 35 AND l.title = 'Лекция 3. Кто участвует и на чём' AND q.id = 1115 AND q.ext_id = 'ooc-poip-q06';
INSERT OR IGNORE INTO lecture_quiz (lecture_id, question_id, position, quote) SELECT l.id, q.id, 3, '- Госорганизации участвуют только на фракционном транспорте (Demorgan 240 минут). - При ограблении Военных складов / Объекта 7 / РЛС Орбиты с вооружённой охраной криминал вправе убрать охрану — и тогда обязан начать ограбление (п. 2.1). - Похищать / грабить сотрудников во время события запрещено.' FROM lectures l, questions q WHERE l.id = 35 AND l.title = 'Лекция 3. Кто участвует и на чём' AND q.id = 1118 AND q.ext_id = 'ooc-poip-q09';
INSERT OR IGNORE INTO lecture_quiz (lecture_id, question_id, position, quote) SELECT l.id, q.id, 1, '**4.2** Для перехвата поставки (ограбления) необходимо организовать перекрытие дороги, состоящее не менее, чем из 4-х автомобилей. [Demorgan 240 минут, в случае утери матовозки по вине нарушителей - поставка/ограбление изымается и засчитывается проводящей фракции]' FROM lectures l, questions q WHERE l.id = 36 AND l.title = 'Лекция 4. Перекрытия и колонна' AND q.id = 1115 AND q.ext_id = 'ooc-poip-q06';
INSERT OR IGNORE INTO lecture_quiz (lecture_id, question_id, position, quote) SELECT l.id, q.id, 2, '**4.6.** Запрещено принимать участие в перехвате поставки после смерти на самом событии. [Demorgan RK]' FROM lectures l, questions q WHERE l.id = 36 AND l.title = 'Лекция 4. Перекрытия и колонна' AND q.id = 1126 AND q.ext_id = 'ooc-poip-q17';
INSERT OR IGNORE INTO lecture_quiz (lecture_id, question_id, position, quote) SELECT l.id, q.id, 3, '**4.10.** В случае перекрытия колонна обязана остановиться и первой начать перестрелку. [Demorgan 120 минут]' FROM lectures l, questions q WHERE l.id = 36 AND l.title = 'Лекция 4. Перекрытия и колонна' AND q.id = 1121 AND q.ext_id = 'ooc-poip-q12';
