INSERT OR IGNORE INTO lecture_quiz (lecture_id, question_id, position, quote) SELECT l.id, q.id, 1, '**Исключительное право (п. 6.42).** ГУ ВП в лице Военной комендатуры и Батальона ВП имеет исключительное право (помимо Командира бригады и его заместителей) на составление, выдачу, исполнение и контроль дисциплинарных взысканий в отношении всех военнослужащих бригады.' FROM lectures l, questions q WHERE l.id = 38 AND l.title = 'Лекция 2. Задачи и полномочия подразделений ГУ ВП' AND q.id = 1141 AND q.ext_id = 'osnovy-q14';
INSERT OR IGNORE INTO lecture_quiz (lecture_id, question_id, position, quote) SELECT l.id, q.id, 2, '- рассмотрение жалоб на военнослужащих бригады и принятие решений по ним; - выдачу дисциплинарных взысканий и контроль их исполнения; - рассмотрение жалоб на действия (бездействие) сотрудников ГУ ВП; - рассмотрение рапортов на снятие дисциплинарных взысканий; - выявление, предупреждение и пресечение правонарушений в бригаде; - содержание на гауптвахте военнослужащих, подвергнутых дисциплинарному аресту; - охрану объектов, определённых Командиром бригады.' FROM lectures l, questions q WHERE l.id = 38 AND l.title = 'Лекция 2. Задачи и полномочия подразделений ГУ ВП' AND q.id = 1134 AND q.ext_id = 'osnovy-q07';
INSERT OR IGNORE INTO lecture_quiz (lecture_id, question_id, position, quote) SELECT l.id, q.id, 3, '- патрульную службу, в том числе в районах учений, на специальных, гарнизонных и иных мероприятиях; - предупреждение, выявление и пресечение правонарушений военнослужащих на территории части и за её пределами, устранение их причин; - охрану места преступления и сохранность следов в пределах полномочий; - розыск и задержание военнослужащих, самовольно покинувших часть, и тех, о преступлениях которых у ГУ ВП есть информация; - розыск похищенного (утраченного) военного имущества; - рассмотрение жалоб на военнослужащих бригады; - выдачу дисциплинарных взысканий, утверждённых Командиром бригады, ег' FROM lectures l, questions q WHERE l.id = 38 AND l.title = 'Лекция 2. Задачи и полномочия подразделений ГУ ВП' AND q.id = 1140 AND q.ext_id = 'osnovy-q13';
INSERT OR IGNORE INTO lecture_quiz (lecture_id, question_id, position, quote) SELECT l.id, q.id, 1, 'а) задержание; б) доставление; в) гауптвахта на срок **не более 30 минут** (подозреваемые и обвиняемые содержатся на гауптвахте в порядке, предусмотренном Процессуальным кодексом РФ); г) личный досмотр, досмотр вещей, личного и служебного транспорта; д) временное отстранение от служебных обязанностей; е) на время служебной проверки — запрет покидать территорию части (**казарменное положение**).' FROM lectures l, questions q WHERE l.id = 39 AND l.title = 'Лекция 3. Дисциплинарная практика: меры, взыскания, сроки' AND q.id = 1144 AND q.ext_id = 'osnovy-q17';
INSERT OR IGNORE INTO lecture_quiz (lecture_id, question_id, position, quote) SELECT l.id, q.id, 2, '| Взыскание | Важно помнить | |---|---| | Предупреждение (замечание) | 3 предупреждения = 1 выговор | | Дисциплинарный арест | не более 30 минут | | Выговор | 3 выговора влекут увольнение с должности | | Увольнение с занимаемой должности | — |' FROM lectures l, questions q WHERE l.id = 39 AND l.title = 'Лекция 3. Дисциплинарная практика: меры, взыскания, сроки' AND q.id = 1147 AND q.ext_id = 'osnovy-q20';
INSERT OR IGNORE INTO lecture_quiz (lecture_id, question_id, position, quote) SELECT l.id, q.id, 3, 'Пока действует взыскание: запрет на отгул; запрет на повышение до снятия выговора; ограничение на получение предметов со склада; запрет на увольнение/перевод; запрет на получение или обновление военного билета до снятия выговора.' FROM lectures l, questions q WHERE l.id = 39 AND l.title = 'Лекция 3. Дисциплинарная практика: меры, взыскания, сроки' AND q.id = 1153 AND q.ext_id = 'osnovy-q26';
INSERT OR IGNORE INTO lecture_quiz (lecture_id, question_id, position, quote) SELECT l.id, q.id, 1, 'а) назначают **оперативного дежурного**, который остаётся на территории части и оперативно передаёт информацию; б) остальные выдвигаются **в патрулирование** в районы рядом с частью и стратегическими объектами; в) ожидают дальнейших инструкций начальника подразделения.' FROM lectures l, questions q WHERE l.id = 40 AND l.title = 'Лекция 4. Действия ВП по тревоге, связь и общение с гражданскими' AND q.id = 1154 AND q.ext_id = 'osnovy-q27';
INSERT OR IGNORE INTO lecture_quiz (lecture_id, question_id, position, quote) SELECT l.id, q.id, 2, 'Военнослужащие ВП прибывают на последнее место оповещения (кроме охраны пункта призыва или патруля далеко от части), далее:' FROM lectures l, questions q WHERE l.id = 40 AND l.title = 'Лекция 4. Действия ВП по тревоге, связь и общение с гражданскими' AND q.id = 1155 AND q.ext_id = 'osnovy-q28';
INSERT OR IGNORE INTO lecture_quiz (lecture_id, question_id, position, quote) SELECT l.id, q.id, 3, 'Гражданским считается любой человек в гражданской одежде (не в форме гос. структур). С гражданскими обращаются словами **«Гражданин»** / **«Гражданка»**; нецензурная брань и оскорбления запрещены.' FROM lectures l, questions q WHERE l.id = 40 AND l.title = 'Лекция 4. Действия ВП по тревоге, связь и общение с гражданскими' AND q.id = 1160 AND q.ext_id = 'osnovy-q33';
INSERT OR IGNORE INTO lecture_quiz (lecture_id, question_id, position, quote) SELECT l.id, q.id, 1, '- Отчёт отправляется **до 19:00 МСК каждого воскресенья** по установленной форме (в канал «еженедельные отчёты» или через сайт ГУ ВП). - Премия выплачивается **только** при отчёте в срок; выплату проводят Командир бригады и Командир батальона ВП до четверга следующей недели. - Нет отчёта: первый раз — **предупреждение**, повторно — **выговор**, третий раз — **увольнение** из ГУ ВП. - Ссылки в отчёте должны работать 7 дней; правка — в том же отчёте, новый не создаётся. - На фотофиксации из игры должен быть виден весь экран и включена бодикамера.' FROM lectures l, questions q WHERE l.id = 41 AND l.title = 'Лекция 5. Служба в ГУ ВП: отчёт, план, портал' AND q.id = 1161 AND q.ext_id = 'osnovy-q34';
INSERT OR IGNORE INTO lecture_quiz (lecture_id, question_id, position, quote) SELECT l.id, q.id, 2, '- Отчёт отправляется **до 19:00 МСК каждого воскресенья** по установленной форме (в канал «еженедельные отчёты» или через сайт ГУ ВП). - Премия выплачивается **только** при отчёте в срок; выплату проводят Командир бригады и Командир батальона ВП до четверга следующей недели. - Нет отчёта: первый раз — **предупреждение**, повторно — **выговор**, третий раз — **увольнение** из ГУ ВП. - Ссылки в отчёте должны работать 7 дней; правка — в том же отчёте, новый не создаётся. - На фотофиксации из игры должен быть виден весь экран и включена бодикамера.' FROM lectures l, questions q WHERE l.id = 41 AND l.title = 'Лекция 5. Служба в ГУ ВП: отчёт, план, портал' AND q.id = 1162 AND q.ext_id = 'osnovy-q35';
INSERT OR IGNORE INTO lecture_quiz (lecture_id, question_id, position, quote) SELECT l.id, q.id, 3, '- **Учебный отдел** — курсы двух систем: «Система званий» и «Система должностей»; тема → короткие лекции → полная выгрузка → видео → экзамен. - **Отчёты** и **Премирование** — еженедельный отчёт и расчёт премии по приказу № 01_10. - **База данных** — инструкции и полные выгрузки тем (выгрузка открывается после всех лекций темы). - **Личные дела** ведёт только старший состав ГУ ВП. - **Переаттестация** видна, только когда администратор выдал доступ (на время и на число попыток).' FROM lectures l, questions q WHERE l.id = 41 AND l.title = 'Лекция 5. Служба в ГУ ВП: отчёт, план, портал' AND q.id = 1165 AND q.ext_id = 'osnovy-q38';
INSERT OR IGNORE INTO lecture_quiz (lecture_id, question_id, position, quote) SELECT l.id, q.id, 1, 'Сотрудник ВП в любой ситуации — **представитель власти и лицо бригады**. Задержанный, нарушитель или свидетель оценивает не только ваши слова, но и то, как вы стоите, смотрите, говорите. Профессиональная позиция складывается из трёх опор:' FROM lectures l, questions q WHERE l.id = 42 AND l.title = 'Лекция 1. Профессиональная позиция сотрудника ВП' AND q.id = 1171 AND q.ext_id = 'psy-q06';
INSERT OR IGNORE INTO lecture_quiz (lecture_id, question_id, position, quote) SELECT l.id, q.id, 2, 'Цель контакта — законный результат: пресечь нарушение, установить личность, задержать или передать дело. Спор «кто прав», ответные оскорбления, желание «поставить на место» только удлиняют контакт и повышают риск силы. Правило: **вас не должно задевать то, что говорит нарушитель**, — вы реагируете на действия, а не на слова.' FROM lectures l, questions q WHERE l.id = 42 AND l.title = 'Лекция 1. Профессиональная позиция сотрудника ВП' AND q.id = 1166 AND q.ext_id = 'psy-q01';
INSERT OR IGNORE INTO lecture_quiz (lecture_id, question_id, position, quote) SELECT l.id, q.id, 3, 'Цель контакта — законный результат: пресечь нарушение, установить личность, задержать или передать дело. Спор «кто прав», ответные оскорбления, желание «поставить на место» только удлиняют контакт и повышают риск силы. Правило: **вас не должно задевать то, что говорит нарушитель**, — вы реагируете на действия, а не на слова.' FROM lectures l, questions q WHERE l.id = 42 AND l.title = 'Лекция 1. Профессиональная позиция сотрудника ВП' AND q.id = 1170 AND q.ext_id = 'psy-q05';
INSERT OR IGNORE INTO lecture_quiz (lecture_id, question_id, position, quote) SELECT l.id, q.id, 1, '1. **Представьтесь и обозначьте статус**: подразделение, звание, фамилия. Человек должен понимать, кто с ним говорит. 2. **Назовите причину** обращения или задержания коротко и понятно. 3. **Объясните, что будет дальше**: «Сейчас досмотр, затем проедем в комендатуру». 4. **Дайте выбор там, где он есть**: «Вы можете сами показать документы или я помогу их достать». Выбор снижает сопротивление. 5. **Подтвердите понимание**: «Вам понятно, что сейчас происходит?»' FROM lectures l, questions q WHERE l.id = 43 AND l.title = 'Лекция 2. Как не допустить конфликт' AND q.id = 1173 AND q.ext_id = 'psy-q08';
INSERT OR IGNORE INTO lecture_quiz (lecture_id, question_id, position, quote) SELECT l.id, q.id, 2, '1. **Представьтесь и обозначьте статус**: подразделение, звание, фамилия. Человек должен понимать, кто с ним говорит. 2. **Назовите причину** обращения или задержания коротко и понятно. 3. **Объясните, что будет дальше**: «Сейчас досмотр, затем проедем в комендатуру». 4. **Дайте выбор там, где он есть**: «Вы можете сами показать документы или я помогу их достать». Выбор снижает сопротивление. 5. **Подтвердите понимание**: «Вам понятно, что сейчас происходит?»' FROM lectures l, questions q WHERE l.id = 43 AND l.title = 'Лекция 2. Как не допустить конфликт' AND q.id = 1174 AND q.ext_id = 'psy-q09';
INSERT OR IGNORE INTO lecture_quiz (lecture_id, question_id, position, quote) SELECT l.id, q.id, 3, '- приказ без объяснения причины; - обращение на «ты», насмешка, грубость (Устав прямо запрещает нецензурную брань и оскорбления в общении с гражданскими — обращение «Гражданин» / «Гражданка»); - угрозы, которые вы не собираетесь или не вправе выполнять; - спор о второстепенном («а почему вы так смотрите»); - публичное унижение при свидетелях; - нарушение личного пространства без необходимости.' FROM lectures l, questions q WHERE l.id = 43 AND l.title = 'Лекция 2. Как не допустить конфликт' AND q.id = 1176 AND q.ext_id = 'psy-q11';
INSERT OR IGNORE INTO lecture_quiz (lecture_id, question_id, position, quote) SELECT l.id, q.id, 1, 'Агрессия задержанного чаще всего — реакция на **страх, стыд, ощущение несправедливости или потерю контроля**. Иногда это расчёт: спровоцировать сотрудника, чтобы потом жаловаться. В обоих случаях ваша реакция должна быть одинаковой — спокойной и законной.' FROM lectures l, questions q WHERE l.id = 44 AND l.title = 'Лекция 3. Агрессивный задержанный: что происходит и что делать' AND q.id = 1179 AND q.ext_id = 'psy-q14';
INSERT OR IGNORE INTO lecture_quiz (lecture_id, question_id, position, quote) SELECT l.id, q.id, 2, '- **Не отвечайте агрессией на агрессию.** Ответная грубость почти всегда поднимает конфликт на следующую стадию. - **Короткие фразы.** Человек в гневе плохо воспринимает длинные объяснения: «Остановитесь. Руки на виду. Вы задержаны за…» - **Называйте поведение, а не личность**: «Вы кричите — так мы ничего не решим», а не «Ты неадекватный». - **Дайте «выход с сохранением лица»**: «Давайте спокойно, и через пять минут всё оформим». - **Не обещайте того, чего не можете** («сейчас отпущу») — обман разрушает доверие и вызывает новую вспышку. - **Безопасность прежде всего**: дистанция, напарник, под' FROM lectures l, questions q WHERE l.id = 44 AND l.title = 'Лекция 3. Агрессивный задержанный: что происходит и что делать' AND q.id = 1184 AND q.ext_id = 'psy-q19';
INSERT OR IGNORE INTO lecture_quiz (lecture_id, question_id, position, quote) SELECT l.id, q.id, 3, '- **Не отвечайте агрессией на агрессию.** Ответная грубость почти всегда поднимает конфликт на следующую стадию. - **Короткие фразы.** Человек в гневе плохо воспринимает длинные объяснения: «Остановитесь. Руки на виду. Вы задержаны за…» - **Называйте поведение, а не личность**: «Вы кричите — так мы ничего не решим», а не «Ты неадекватный». - **Дайте «выход с сохранением лица»**: «Давайте спокойно, и через пять минут всё оформим». - **Не обещайте того, чего не можете** («сейчас отпущу») — обман разрушает доверие и вызывает новую вспышку. - **Безопасность прежде всего**: дистанция, напарник, под' FROM lectures l, questions q WHERE l.id = 44 AND l.title = 'Лекция 3. Агрессивный задержанный: что происходит и что делать' AND q.id = 1185 AND q.ext_id = 'psy-q20';
INSERT OR IGNORE INTO lecture_quiz (lecture_id, question_id, position, quote) SELECT l.id, q.id, 1, '1. Дайте человеку договорить (если это безопасно). 2. Перескажите коротко: «Вы считаете, что вас остановили несправедливо». 3. Признайте чувство, не соглашаясь с нарушением: «Понимаю, что неприятно. Но порядок такой». 4. Вернитесь к делу: «Давайте закончим проверку».' FROM lectures l, questions q WHERE l.id = 45 AND l.title = 'Лекция 4. Правила коммуникации: слова, тон, дистанция' AND q.id = 1187 AND q.ext_id = 'psy-q22';
INSERT OR IGNORE INTO lecture_quiz (lecture_id, question_id, position, quote) SELECT l.id, q.id, 2, '1. Дайте человеку договорить (если это безопасно). 2. Перескажите коротко: «Вы считаете, что вас остановили несправедливо». 3. Признайте чувство, не соглашаясь с нарушением: «Понимаю, что неприятно. Но порядок такой». 4. Вернитесь к делу: «Давайте закончим проверку».' FROM lectures l, questions q WHERE l.id = 45 AND l.title = 'Лекция 4. Правила коммуникации: слова, тон, дистанция' AND q.id = 1186 AND q.ext_id = 'psy-q21';
INSERT OR IGNORE INTO lecture_quiz (lecture_id, question_id, position, quote) SELECT l.id, q.id, 3, '- Стойка вполоборота, руки видны, без резких движений. - Дистанция — не ближе вытянутой руки без необходимости. - Взгляд — спокойный, без «сверления» и без бегающих глаз. - Не нависайте над сидящим человеком, не тычьте пальцем.' FROM lectures l, questions q WHERE l.id = 45 AND l.title = 'Лекция 4. Правила коммуникации: слова, тон, дистанция' AND q.id = 1189 AND q.ext_id = 'psy-q24';
INSERT OR IGNORE INTO lecture_quiz (lecture_id, question_id, position, quote) SELECT l.id, q.id, 1, '- **Законность и равенство.** Одинаковый порядок для всех — независимо от звания, знакомства, симпатии. - **Уважение к достоинству.** Задержанный — не враг; он остаётся человеком с правами, которые вы обязаны разъяснить. - **Никаких унижений и «наказаний сверх закона»**: насмешки, издевательства, лишние меры — недопустимы. - **Честность.** В рапорте и докладе — только то, что было; не приукрашивать и не скрывать свои ошибки. - **Конфиденциальность.** Сведения о задержанных и личных делах не обсуждают вне службы. - **Пример для других.** Сотрудник надзорного органа сам соблюдает уставы строже в' FROM lectures l, questions q WHERE l.id = 46 AND l.title = 'Лекция 5. Этика сотрудника и работа после конфликта' AND q.id = 1195 AND q.ext_id = 'psy-q30';
INSERT OR IGNORE INTO lecture_quiz (lecture_id, question_id, position, quote) SELECT l.id, q.id, 2, 'Если вы ошиблись (не тот человек, неверное основание) — спокойно признайте, извинитесь и исправьте. Это укрепляет авторитет, а не ослабляет его.' FROM lectures l, questions q WHERE l.id = 46 AND l.title = 'Лекция 5. Этика сотрудника и работа после конфликта' AND q.id = 1194 AND q.ext_id = 'psy-q29';
INSERT OR IGNORE INTO lecture_quiz (lecture_id, question_id, position, quote) SELECT l.id, q.id, 3, '1. **Доведите дело до конца по порядку**: оформление, передача, доклад. 2. **Проверьте состояние** задержанного и своё. Нужна медицинская помощь — окажите или вызовите. 3. **Разбор с напарником**: что сработало, что нет, где можно было снизить напряжение раньше. 4. **Не уносите эмоции в следующий контакт**: следующий человек не виноват в предыдущем конфликте.' FROM lectures l, questions q WHERE l.id = 46 AND l.title = 'Лекция 5. Этика сотрудника и работа после конфликта' AND q.id = 1196 AND q.ext_id = 'psy-q31';
